<?php
namespace App\Http\Controllers;
use App\Models\LoginEvent; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\DB;
class AuthController extends Controller {
 public function showLogin(){return view('auth.login');} public function create(){return $this->showLogin();}
 public function login(Request $request){return $this->performLogin($request);} public function store(Request $request){return $this->performLogin($request);}
 private function performLogin(Request $request){$credentials=$request->validate(['login'=>['required','string'],'password'=>['required','string']]);$credentials['is_active']=true;if(!Auth::attempt($credentials,$request->boolean('remember')))return back()->withErrors(['login'=>'Неверный логин или пароль.'])->onlyInput('login');$request->session()->regenerate();$u=$request->user();DB::table('login_activities')->insert(['user_id'=>$u->id,'ip'=>$request->ip(),'user_agent'=>substr((string)$request->userAgent(),0,500),'logged_in_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);if(DB::getSchemaBuilder()->hasTable('login_events'))LoginEvent::create(['user_id'=>$u->id,'logged_in_at'=>now(),'ip'=>$request->ip(),'user_agent'=>substr((string)$request->userAgent(),0,500)]);return redirect()->intended(route('dashboard'));}
 public function logout(Request $request){return $this->performLogout($request);} public function destroy(Request $request){return $this->performLogout($request);} private function performLogout(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');}
}